package org.opentrafficmap.receiver.asn1

import org.opentrafficmap.receiver.nav.MiniJson
import java.io.InputStream
import java.math.BigInteger

/**
 * Type table generated by tools/asn1gen/gen_its_schema.py from the official ASN.1 definitions
 * (via pycrate). See that script for the JSON layout.
 */
class AsnSchema private constructor(val name: String, val roots: Map<String, Int>, private val types: List<Node>) {

    sealed class Node { abstract val tn: String }
    class Field(val name: String, val tid: kotlin.Int, val flag: kotlin.Int) { val optional get() = flag != 0 }
    class Seq(val ext: Boolean, val root: List<Field>, val extNest: List<ExtItem>, override val tn: String) : Node() {
        val optCount = root.count { it.optional }
    }
    sealed class ExtItem
    class ExtSingle(val name: String, val tid: kotlin.Int) : ExtItem()
    class ExtGroup(val fields: List<Field>) : ExtItem()
    class Alt(val name: String, val tid: kotlin.Int, val tagClass: kotlin.Int, val tagNum: kotlin.Int)
    class Choice(val ext: Boolean, val root: List<Alt>, val extAlts: List<Alt>, override val tn: String) : Node()
    class IntT(val lb: BigInteger?, val ub: BigInteger?, val ext: Boolean, val named: Map<BigInteger, String>, override val tn: String) : Node()
    class EnumT(val root: List<Pair<String, Long>>, val extItems: List<Pair<String, Long>>, val ext: Boolean, override val tn: String) : Node()
    class BoolT(override val tn: String) : Node()
    class NullT(override val tn: String) : Node()
    class OpenT(override val tn: String) : Node()
    class BitsT(val lb: Long?, val ub: Long?, val ext: Boolean, val named: Map<kotlin.Int, String>, override val tn: String) : Node()
    class OctT(val lb: Long?, val ub: Long?, val ext: Boolean, override val tn: String) : Node()
    class StrT(val kind: String, val lb: Long?, val ub: Long?, val ext: Boolean, override val tn: String) : Node()
    class SeqOfT(val elem: kotlin.Int, val lb: Long?, val ub: Long?, val ext: Boolean, override val tn: String) : Node()

    fun node(tid: kotlin.Int): Node = types[tid]

    companion object {
        fun load(name: String, input: InputStream): AsnSchema {
            val root = MiniJson.parse(input.bufferedReader().readText()) as Map<*, *>
            val roots = (root["roots"] as Map<*, *>).entries.associate { (k, v) -> k as String to (v as Number).toInt() }
            val types = (root["types"] as List<*>).map { parseNode(it as List<*>) }
            return AsnSchema(name, roots, types)
        }

        private fun big(v: Any?): BigInteger? = when (v) {
            null -> null
            is Number -> BigInteger.valueOf(v.toLong()).takeIf { v.toDouble() == it.toDouble() }
                ?: java.math.BigDecimal(v.toDouble()).toBigInteger()
            else -> BigInteger(v.toString())
        }
        private fun lng(v: Any?): Long? = (v as? Number)?.toLong()
        private fun bool(v: Any?) = (v as? Number)?.toInt() == 1
        private fun str(v: Any?) = v as? String ?: ""

        private fun fields(l: Any?) = (l as List<*>).map { f ->
            f as List<*>; Field(f[0] as String, (f[1] as Number).toInt(), (f[2] as Number).toInt())
        }
        private fun alts(l: Any?) = (l as List<*>).map { a ->
            a as List<*>; Alt(a[0] as String, (a[1] as Number).toInt(), (a[2] as Number).toInt(), (a[3] as Number).toInt())
        }
        private fun pairs(l: Any?) = (l as List<*>).map { p -> p as List<*>; (p[0] as String) to (p[1] as Number).toLong() }

        private fun parseNode(n: List<*>): Node {
            val tn = str(n.last())
            return when (n[0]) {
                "seq" -> Seq(bool(n[1]), fields(n[2]), (n[3] as List<*>).map { e ->
                    e as List<*>
                    if (e[0] == "[[") ExtGroup(fields(e[1])) else ExtSingle(e[0] as String, (e[1] as Number).toInt())
                }, tn)
                "ch" -> Choice(bool(n[1]), alts(n[2]), alts(n[3]), tn)
                "int" -> IntT(big(n[1]), big(n[2]), bool(n[3]),
                    (n[4] as List<*>).associate { p -> p as List<*>; big(p[1])!! to (p[0] as String) }, tn)
                "enum" -> EnumT(pairs(n[1]), pairs(n[2]), bool(n[3]), tn)
                "bool" -> BoolT(tn)
                "null" -> NullT(tn)
                "open" -> OpenT(tn)
                "bits" -> BitsT(lng(n[1]), lng(n[2]), bool(n[3]),
                    (n[4] as List<*>).associate { p -> p as List<*>; (p[1] as Number).toInt() to (p[0] as String) }, tn)
                "oct" -> OctT(lng(n[1]), lng(n[2]), bool(n[3]), tn)
                "str" -> StrT(n[1] as String, lng(n[2]), lng(n[3]), bool(n[4]), tn)
                "sof" -> SeqOfT((n[1] as Number).toInt(), lng(n[2]), lng(n[3]), bool(n[4]), tn)
                else -> throw IllegalArgumentException("unknown node kind ${n[0]}")
            }
        }
    }
}
